"""
core/problem_lens_en.py — เลนส์ปัญหาฉบับภาษาอังกฤษ ของเลนส์ที่เดิมมีแต่ภาษาไทย

คลังภาษาอังกฤษ 164 เรื่อง: 128 เรื่อง (78%) ได้ "Let's lay this out step by step." เพราะเลนส์ส่วนใหญ่มีแต่ภาษาไทย
และ "I'm drowning in student loan payments" ได้ขั้นตอนช่วยคนจมน้ำ (แก้สำนวนแล้วใน kernel_voice)

แต่ละรายการ: key → (regex, open, [3 ขั้น], ask, vega) — ข้อเท็จจริงของไทยเขียนเป็น "In Thailand: …"
แล้วบอกให้คนในประเทศอื่นหาหน่วยงานท้องถิ่น ไม่เดาเบอร์ของประเทศอื่น
"""
from __future__ import annotations

import re

_KIN = r"(?:mom|mum|mother|dad|father|wife|husband|partner|son|daughter|kid|child|parents|brother|sister|grand(?:ma|pa|mother|father|parents)|aunt|uncle|friend|in-?laws?|family)"
_PAIR = r"(?:boyfriend|girlfriend|partner|husband|wife|bf|gf|fianc[eé]e?)"

EN = {
    "heart_signs": (r"\b(?:heart (?:races|is racing|pounds|palpitations)|palpitations|(?:get|getting) out of breath (?:easily|quickly)|short of breath (?:easily|on stairs))\b",
        "A racing heart and getting breathless easily need checking, not just rest — causes range from simple ones like caffeine, thyroid or anaemia to heart rhythm problems, and only tests can tell them apart.",
        ["See a doctor this week and ask for an ECG and blood tests; say how long it's been happening and what you were doing.",
         "Log each episode: time, activity, how long it lasted, caffeine or energy drinks beforehand.",
         "If you get chest pain, can't catch your breath, feel faint, or palpitations last over 15–20 minutes, go to emergency now (1669 in Thailand)."],
        "Does it happen at rest, or when you exert yourself — like climbing stairs?",
        "There isn't enough information to say what it is, and guessing is risky — the variable that matters is the test result, and the danger signs are clear."),
    "lump_wait": (r"\b(?:found|have) a lump\b|\bwaiting (?:for|on) (?:my )?(?:biopsy|test|scan) results\b",
        "Waiting for results is often harder than hearing them, because the mind fills in the worst answer — most lumps that get checked are not cancer, and if it is, finding it early is what makes treatment work. Getting it checked was the right move.",
        ["Ask exactly when and how results will come — a date helps stop the looping.",
         "Write your questions down for the results appointment and bring someone you trust.",
         "Limit searching online to once a day — most of what you'll read isn't your case."],
        "When are the results due, and who could come with you?",
        "Nothing to decide until the result arrives — the only useful work now is preparing questions and support."),
    "not_eating": (r"\b(?:haven'?t|can'?t|cannot) (?:been able to )?eat(?:en)?\b[^\n]{0,20}?\b(?:days|a week|weeks)\b|\bno appetite for (?:days|weeks)\b",
        "Not eating for days is a signal to find the cause — it can be physical (stomach, infection, medication) or emotional (grief, heavy stress), and the other symptoms usually tell which.",
        ["Take small, frequent liquid meals — milk, soup, porridge. Your body needs fuel to think clearly.",
         "See a doctor if there's weight loss, vomiting, stomach pain, black stools, you can't keep water down, or you feel faint.",
         "If it's because your heart is heavy, talk to someone — sadness that stops you eating deserves care."],
        "Did something happen before you stopped eating, or are there physical symptoms too?",
        "First separate physical from emotional causes — weight loss, vomiting or not keeping water down means a doctor first."),
    "back_pain": (r"\b(?:back pain|my back hurts)\b[^\n]{0,24}?\b(?:months|years|chronic|every day|won'?t go away)\b|\bchronic back pain\b",
        "Most long-term back pain comes from muscles and repeated posture, and gets better with movement rather than bed rest — but some signs mean nerves are involved and need checking quickly.",
        ["Get seen soon if you have leg numbness or weakness, numbness around the groin, trouble controlling bladder or bowel, fever, or unexplained weight loss.",
         "Otherwise, ask for physiotherapy or rehabilitation medicine to get exercises suited to you.",
         "Look at what you repeat daily: sitting over an hour, how you lift, desk and screen height. Getting up every hour helps more than you'd think."],
        "Does the pain shoot down your leg, or come with numbness or weakness?",
        "The variable that separates minor from serious is nerve symptoms — without them, it's a repeated-posture problem you can change."),
    "drink_to_sleep": (r"\b(?:drink|drinking|need (?:a )?drinks?|have (?:a )?(?:beer|wine|whisky))\b[^\n]{0,20}?\b(?:to (?:fall )?(?:asleep|sleep)|before bed every)\b",
        "Alcohol helps you fall asleep but makes sleep shallow and wakes you at night — the more you drink to sleep, the worse sleep gets, so you need more. That loop is what to break.",
        ["Cut down gradually rather than stopping cold if you've drunk heavily every day — stopping suddenly can cause shaking, palpitations and severe insomnia, so talk to a doctor.",
         "Find what keeps you awake in the first place — that's what the alcohol is covering.",
         "In Thailand the 1413 quit-drinking line is free; sleep clinics in hospitals can help too."],
        "If you didn't drink tonight, what do you think would keep you awake?",
        "It's a self-reinforcing loop — the cut point is the cause of the insomnia, not the alcohol alone."),
    "low_mood": (r"\b(?:sad|depressed|down|low)\b[^\n]{0,10}?\bfor (?:two|three|several|a few|\d+) (?:weeks|months)\b|\bnothing (?:feels good|makes me happy)\b|\bfeel (?:empty|worthless) every day\b",
        "Sadness that lasts weeks, or feeling empty or worthless every day, can be depression — an illness that's treatable, not a weakness. And it always makes you see yourself as worse than you are.",
        ["Ask yourself two things: in the last two weeks, have I felt down or hopeless most days? Have I lost interest in things I used to enjoy? A yes to either means it's worth talking to a professional.",
         "See a doctor or psychologist, or call a support line to talk first (1323 in Thailand, free 24h).",
         "Meanwhile keep the basics: same wake time, daylight once a day, regular meals, and tell one person you're struggling."],
        "How long has it felt like this, and is there any time of day when it lifts a little?",
        "Duration and impact are the key variables — over two weeks and affecting eating, sleep or work means it needs treatment, and treatment works."),
    "worry": (r"\b(?:can'?t stop (?:overthinking|worrying)|overthink(?:ing)? (?:everything|past)|anxious all the time|constant(?:ly)? (?:anxious|worrying)|ruminat\w+)\b",
        "Looping thoughts don't produce new answers — it's the brain trying to guard against a danger it can't solve in your head. The way out isn't thinking it through, it's separating what you can act on from what you can't.",
        ["Write everything looping in your head on paper, split into 'can act on' and 'can't'. Pick one small step from the first; leave the second on the page.",
         "Set a 15-minute daily 'worry time'; when worries come at other times, note them for later.",
         "If anxiety stops you sleeping or eating for weeks, see a professional — anxiety disorders are treatable."],
        "What's the thought that loops most often?",
        "Rumination is a loop with no new input — break it by making it concrete: write, sort, take one step."),
    "social_fear": (r"\b(?:scared|afraid|terrified) of (?:social situations|people|parties|talking to people)\b|\bsocial anxiety\b",
        "Social fear runs on avoidance — avoiding feels safer for a moment but makes the fear bigger each time. The way out is approaching in steps you can handle, not forcing one big leap.",
        ["Make a fear ladder from easiest to hardest (greeting a shop assistant → asking a question in class → a small gathering), and do the first rung this week.",
         "Prepare two or three opening and closing lines — starting and ending are the hardest parts.",
         "If it costs you school, work or important chances, social anxiety responds well to therapy."],
        "Which situation is least scary but you still avoid?",
        "The mechanism is avoidance reinforcing fear — the variable you can change is how often you approach in small doses."),
    "cant_say_no": (r"\b(?:can'?t|cannot|never) say no\b|\bpeople[- ]pleas\w+\b",
        "Not being able to say no usually comes from fear of not being liked — but every yes to something you don't want is a no to your own time and energy.",
        ["Buy time instead of answering on the spot: 'Let me check and get back to you.'",
         "Decline briefly without long explanations — the more you explain, the more room for negotiation.",
         "Practise on small things with safe people before big things with people who have power over you."],
        "What have you agreed to that you don't actually want to do?",
        "Every yes has a hidden cost in your time — the variable you control is the gap between request and answer."),
    "anger": (r"\b(?:lose my temper|anger issues|snap at|yell at|blow up at|short[- ]tempered)\b",
        "Noticing that you blow up at people close to you is an important first step. Anger usually isn't about the moment — it builds from exhaustion, poor sleep or things left unsaid, and lands on whoever feels safest.",
        ["Learn your warning signs (hot face, clenched fists, rising voice) and step out for 10 minutes: 'I need a break, I'll come back to talk.'",
         "Notice when it happens most — hungry, tired, after work — and fix that condition first.",
         "Once calm, apologise specifically. If you start breaking things or hurting anyone, get professional help."],
        "The last time you blew up, what came just before?",
        "Anger is the output of accumulated load — the quickest levers are the conditions (sleep, hunger, work) and a 10-minute pause."),
    "burnout": (r"\b(?:burn(?:ed|t) out|burnout|no motivation|dread (?:going to )?work|hate going to work)\b",
        "Burnout doesn't mean you're lazy — it happens when what you give out exceeds what comes back for too long: energy, time and meaning. Find which is missing before deciding to quit.",
        ["Work out what's draining you: too much work, meaningless work, the people, or never truly resting — each needs a different fix.",
         "Take 2–3 real days off. If you recover, it's accumulated fatigue; if nothing changes, it's the job or possibly depression.",
         "Talk to your manager about specific load before resigning — quitting while burned out often carries the exhaustion with you."],
        "If you had a full week off, would you want to go back to this job?",
        "Energy out versus energy back — run negative long enough and the system shuts down. Fix the side you can before an irreversible step like quitting."),
    "kin_refuse_doctor": (rf"\bmy {_KIN}\b[^\n]{{0,40}}?\b(?:refuses?|won'?t|doesn'?t want) (?:to )?(?:see|go to|visit) (?:a |the )?(?:doctor|hospital|therapist)\b",
        "You're not the one who needs to see the doctor, and pushing adults usually makes them resist more. People refuse for reasons they haven't said — fear of the result, the cost, being a burden, or not wanting to admit they're ill.",
        ["Ask without judgement what makes them not want to go, and fix that: go with them, sort out cost, or have someone they listen to ask.",
         "Use reasons they value ('I want you healthy for the grandkids'), not threats. For depression, suggesting help for sleep or tiredness is often easier.",
         "If there are danger signs — trouble breathing, chest pain, confusion, slurred speech, or talk of not wanting to live — call emergency services without waiting for consent."],
        "Have they said why they don't want to go?",
        "What decides it is their reason for refusing, not your effort — address the fear, money or pride, except for danger signs that need help now."),
    "kin_jobless": (rf"\bmy {_KIN}\b[^\n]{{0,20}}?\b(?:lost (?:his|her|their) job|is unemployed)\b[^\n]{{0,40}}?\b(?:move in|live with me|stay with me|borrow|support)\b",
        "Helping family through unemployment is good, but without a frame, temporary help becomes permanent load and money strains the relationship.",
        ["Agree a frame on day one: how long, how much (housing, food), and what they'll do meanwhile (applications per week).",
         "Help them claim their own entitlements — unemployment benefits, job centres.",
         "Only give what doesn't put your own household at risk."],
        "How long can you help without your own household suffering?",
        "Define scope and duration — open-ended help doesn't get them back on their feet and can pull you under too."),
    "kin_belittle": (rf"\bmy {_KIN}\b[^\n]{{0,20}}?\b(?:calls? me|says? I'?m|tells? me I'?m)\b[^\n]{{0,10}}?\b(?:a failure|useless|stupid|worthless|a disappointment|lazy)\b",
        "Repeated words from people close to you cut deeper because you hope they'll see your worth — but what they say reveals their disappointment or pressure more than who you are.",
        ["Split what they say into facts that might be true (e.g. no job yet) and judgements of your whole person ('a failure'). The first you can work on; the second you don't have to accept.",
         "Tell them when you're not fighting: 'When I'm spoken to like that I don't get more motivated, I lose energy. If you want me to change something, tell me what.'",
         "Add other voices to your life — people who value you, things you're good at. If it starts making you feel you don't want to live, reach out to a crisis line."],
        "Is there anything in what they say that you do want to change?",
        "Separate signal from noise: any fact in it is usable data; the judgement of your identity is not data."),
    "silent_treatment": (rf"\bmy {_KIN}\b[^\n]{{0,10}}?\b(?:hasn'?t (?:spoken|talked) to me|won'?t (?:speak|talk) to me|is ignoring me)\b",
        "Long silence usually means something is unresolved and nobody wants to go first — the longer it lasts, the more each waits for the other.",
        ["Open with a short message that doesn't reopen the old issue: 'I miss you. Whenever you're ready, I'd like to talk.'",
         "If you know what caused it, own your part specifically without accepting all of it.",
         "Give them time — if there's no reply, don't chase daily; try again in a week or two."],
        "What happened just before the silence started?",
        "The stalemate persists because going first feels expensive — lower that cost with a message that doesn't require reopening the past."),
    "kin_borrow": (rf"\bmy {_KIN}\b[^\n]{{0,20}}?\b(?:keeps? borrowing|always borrows|asks? (?:me )?for money)\b",
        "Money with family is harder than with strangers because saying no feels like not loving them — but lending and resenting it every time costs the relationship more than the money.",
        ["Set your own rule: only give amounts you can lose without chasing, and call it a gift, not a loan.",
         "Say no to the money, not the person: 'I can't help with cash this month, but I can help you find work or sort out benefits.'",
         "For larger sums you need back, put it in writing, even with family."],
        "How much has gone out in total, and how much can you lose without it affecting your home?",
        "The variable is the boundary you set — without one, the person asking sets it, and the amounts grow."),
    # controlling_partner: ไม่มีฉบับอังกฤษ — kernel_voice มี "control_en" (coercive control + สายด่วนไทย/สหรัฐฯ) ที่ดีอยู่แล้ว
    "cheating": (rf"\b(?:my )?{_PAIR}\b[^\n]{{0,10}}?\b(?:is cheating|cheated|has an affair|is having an affair|is seeing someone else)\b|\bfound out (?:my )?{_PAIR} (?:is |was )?cheating\b",
        "Finding out you've been cheated on shakes everything, and the urge to decide immediately — leave now or forgive now — is normal. A good decision needs fuller information and a calmer mind than this.",
        ["Don't decide in the first week. Look after yourself and quietly keep evidence, especially if you're married, have children or shared assets.",
         "When ready, ask what helps decide: is it truly over with the other person, do they take responsibility or blame you, will they be transparent?",
         "If married, get legal advice on your rights (property, child support) before signing or agreeing anything."],
        "What do you most want to know from them right now?",
        "Whether it's repairable shows in their behaviour after being caught — ended, accountable, transparent — not in the apology."),
    "wont_marry": (r"\b(?:won'?t|doesn'?t want to|refuses to) (?:talk about )?(?:marry|get married|marriage)\b|\bwon'?t talk about marriage\b",
        "The real question may not be 'why won't they marry me' but 'do we want the same future?' Waiting without clarity lets years pass without the most important answer.",
        ["Ask directly, when not fighting, what future they see — marriage, children, where to live — and listen for 'not ready yet' versus 'don't want to'.",
         "Say what you want without ultimatums: 'I'd like to be married within a few years. I want to know if we're heading the same way.'",
         "If it's money or readiness, plan in steps together; if they simply don't want it, that's the information you need to decide."],
        "If they said they never want to marry, would you still want this relationship?",
        "What decides it is whether your goals match, not how long you've been together — the longer you wait without data, the higher the cost in time."),
    "divorce_kids": (r"\b(?:want|thinking about|considering) (?:a )?divorce\b[^\n]{0,30}?\b(?:kids?|children|son|daughter)\b",
        "Children aren't hurt only by parents separating — they're hurt by conflict they see every day. Stay or separate, what protects them most is less fighting in front of them and keeping both parents in their lives.",
        ["Before deciding, get legal advice on custody, child support and shared property.",
         "If unsure, try couples or family counselling — it helps whether you repair or separate well.",
         "If you separate, tell the children together in words fit for their age: it's not their fault and you both still love them. Never use them as messengers."],
        "Is it the fighting, feelings that have gone, or is safety an issue too?",
        "Compare both paths on one variable: the level of conflict your children see — whichever lowers it more sustainably is better for them."),
    "lonely_marriage": (r"\b(?:lonely|alone) in (?:my|our) (?:marriage|relationship)\b|\bmarried but (?:feel )?lonely\b",
        "Loneliness in a marriage rarely means love is gone — it usually means work, kids and screens have eaten your time as a couple until only logistics remain.",
        ["Tell your partner without blame: 'I miss us. I'd like time to talk like we used to.'",
         "Build small, regular time: phone-free meals a few times a week, a 20-minute walk together.",
         "If talking turns into fighting every time, see a couples counsellor before the distance becomes a habit."],
        "When did you last feel close, and what were you doing then?",
        "Closeness decays slowly with time not invested — fix it with consistency, not grand gestures."),
    "chores": (rf"\b(?:my )?{_PAIR}\b[^\n]{{0,10}}?\b(?:doesn'?t|won'?t|never) (?:help with|do) (?:any )?(?:housework|chores|dishes|cleaning)\b",
        "The problem isn't the dishes — it's invisible load. The person who has to remember, ask and check is more tired than the one who just does the task, and 'helping' keeps the housework yours.",
        ["List every household task for a week, including invisible ones like meal planning and paying bills.",
         "Assign whole ownership of tasks, not occasional help — they own laundry entirely, from noticing to finishing.",
         "Accept a different standard on tasks you hand over — if you redo them, they'll come back to you."],
        "If you handed one whole task to them, which would it be?",
        "The variable to change is ownership, not frequency of help — if you still have to ask, the mental load is still yours."),
    "partner_spending": (rf"\b(?:my )?{_PAIR}\b[^\n]{{0,10}}?\b(?:spends? (?:too much|way more|more than we earn)|overspends|shopping addiction)\b",
        "Household money fights are rarely about numbers — they're about what money means to each of you (security, joy, reward). Without shared rules, the careful one becomes the police and the other starts hiding spending.",
        ["Look at the numbers together once: total income, essentials, debts — talk from the numbers, not the last purchase.",
         "Use three pots: shared (home, bills, savings), personal money each can spend without asking, and joint goals.",
         "Agree a threshold for discussing purchases first, and bring any hidden debts into the open."],
        "Are there debts or instalments you don't know the full picture of?",
        "The structural problem is no shared rules — separate pots with a discussion threshold beat policing every purchase."),
    "ex_back": (r"\bmy ex\b[^\n]{0,20}?\b(?:wants? (?:me )?back|wants to get back together|reached out|texted me)\b",
        "The key question isn't 'do I still love them' but 'have the reasons we broke up actually changed?' If they haven't, it usually ends in the same place.",
        ["Write the real reasons it ended and look for evidence — actions, not words — that each has changed.",
         "Don't answer right away; the reunion phase is when everything looks best. Give it weeks to see if words match actions.",
         "Ask yourself whether you miss them, or miss not being lonely — they lead to different choices."],
        "Why did it end last time, and what has changed since?",
        "The best predictor is the cause of the last ending — if that variable hasn't changed, the outcome usually won't."),
    "crush_friend": (r"\b(?:crush on|in love with|have feelings for) my (?:best )?friend\b",
        "Fear of losing the friendship is real, but keeping it in has a cost — unspoken feelings already change how you are with them, and most strong friendships survive a respectful confession.",
        ["Look for signs first: do they make time for you, ask about your life, or are they already seeing someone?",
         "If you tell them, give them an easy exit: 'I like you. If you don't feel the same, I'd still love to stay friends.'",
         "If you don't, decide clearly to let it go and give yourself some space."],
        "If they said they didn't feel the same, could you stay friends?",
        "The cost of telling is risk to the friendship; the cost of not telling is time and lingering feelings — the signals they give help decide."),
    "ghosted": (r"\b(?:ghosted|stopped (?:replying|texting|responding)|left me on read|disappeared without)\b",
        "Being ghosted hurts because there's no ending to close it — but disappearing says more about how they handle feelings than about your worth.",
        ["Send one message if you want: 'No worries if you don't want to keep talking. Take care.' Then stop — that closes it on your side.",
         "Don't hunt for what you did wrong — people who vanish usually do it to many.",
         "Archive the chat for a while so you're not checking it."],
        "How long had you been talking before they disappeared?",
        "Their disappearance is data about how they handle conflict — important for anything long-term, and it answers whether to wait."),
    "no_raise": (r"\b(?:no|haven'?t had a|never got a|never had a) (?:raise|pay rise|salary increase)\b",
        "No raise for years usually means you're worth more on the market than you're paid, and the company has no reason to adjust unless someone asks — your leverage is numbers from outside.",
        ["Find your market rate: job ads with salaries, people in your field, annual salary surveys.",
         "Ask your manager with data — achievements in numbers and market rates — and ask 'what would I need to do, and by when, to get an adjustment?'",
         "Apply elsewhere in parallel — a real offer is the best data and your exit if the answer is no."],
        "If you applied elsewhere today, what salary do you think you'd get?",
        "Leverage depends on alternatives — the variable to build is an outside offer, not more effort in the same place."),
    "relocation_offer": (r"\bjob offer\b[^\n]{0,40}?\b(?:move|relocat\w+|another city|another country)\b",
        "This isn't just a higher salary — it's the cost of moving your whole life. Compare the money left after the new cost of living, and what you'd leave behind.",
        ["Calculate real gain: new salary minus rent, transport and trips home — 40% more can shrink to 10%.",
         "Ask what the ad doesn't say: probation, relocation support, growth, and whether you could come back if it fails.",
         "List what you'd leave — family, people you care for, friends — and whether there's a way to compensate."],
        "After the new city's costs, how much more would you actually have each month?",
        "Decide on net income after living costs against non-money costs and reversibility — a reversible move is lower risk."),
    "job_hunt": (r"\b(?:applied (?:to|for) \d+|no interviews|no one (?:will )?hire|can'?t find (?:a )?job|been job hunting for)\b",
        "When many applications get nowhere, the problem is usually one stage of the process, not you as a person — no interviews means the application; interviews but no offers means interviewing or the roles chosen.",
        ["Find where you drop out: applications sent, interviews, which round you pass.",
         "Tailor each application to the ad, use its words, show results as numbers, and have someone in your field read it.",
         "Ask for brief feedback after interviews, and claim unemployment support if you're eligible."],
        "Roughly how many applications, and how many interviews?",
        "It's a funnel: apply → interview → offer — measure each stage and fix the leakiest first instead of applying more the same way."),
    "career_change": (r"\b(?:change|switch) (?:careers?|fields?|industr(?:y|ies))\b",
        "Changing careers doesn't mean starting from zero — many skills transfer, and age matters less than evidence that you can do the new work.",
        ["Test before jumping: small gigs, a personal project or a short course for 2–3 months.",
         "Find a bridge role that uses both your old experience and new skills.",
         "Talk to two or three people in that field about starting pay and real days, and save a buffer for the income dip."],
        "Which of your current skills would carry into the new field?",
        "The risk is the income dip during the switch — reduce it by testing while still earning and choosing bridge roles."),
    "gossip": (r"\b(?:gossip(?:ing)? about me|talk(?:ing)? behind my back|spreading rumou?rs about me)\b",
        "Gossip hurts because you can't control what others say — what you can control is evidence of your work and the people who know you. Hitting back hard often makes rumours seem true.",
        ["Decide whether it's personal dislike or actually affecting your work (reviews, assignments). If it affects work, act; if not, you can let it go.",
         "If you speak up, do it calmly and briefly with the person: 'I heard you said this. If you have an issue with me, tell me directly.'",
         "If it's defamation affecting your job, log dates and details and raise it with your manager or HR."],
        "Is it affecting your work, or mainly your feelings?",
        "The key variable is work impact — if there is some, use facts and formal channels; if not, starving it of energy works best."),
    "hiring": (r"\b(?:can'?t|cannot|struggling to) (?:find|hire|keep) (?:staff|employees|workers|people)\b",
        "If you can't hire at all, your offer probably isn't competitive in today's market (pay, hours, commute) or isn't reaching the right people — find out whether nobody applies, or they apply and don't stay.",
        ["Compare your whole package with nearby employers: pay, days off, meals, housing, flexibility.",
         "Widen channels: community groups, colleges, referral bonuses for current staff, public job centres.",
         "While short-staffed, cut the most labour-heavy or least profitable services and write down procedures so new people learn fast."],
        "Do people not apply at all, or apply and then leave quickly?",
        "This is a price-and-reach problem in the labour market — find which stage leaks (ad → apply → start → stay) and fix that one."),
    "guarantor": (r"\bco-?sign(?:ed|er)?\b[^\n]{0,40}?\b(?:disappeared|stopped paying|won'?t pay|vanished|sued|chasing me)\b|\bguarantor\b[^\n]{0,30}?\b(?:pay|debt|chasing|sued)\b",
        "Co-signing can make you liable for their debt, but there are protections many people don't know — in Thailand, for example, creditors must notify guarantors within a set time after default, and a guarantor can't owe more than the borrower.",
        ["Get documents from the lender: the guarantee contract, the remaining balance and any notice sent to you — check the dates.",
         "Don't sign anything accepting the amount or a new agreement before getting legal advice (in Thailand, the Lawyers Council 1167 is free).",
         "If you pay on their behalf, you can claim it back from the borrower — keep every receipt."],
        "Has the lender sent you a written notice yet, and what date is on it?",
        "What reduces your burden is the documents and notice dates — check before paying or signing, because accepting a balance is hard to undo."),
    "tax": (r"\b(?:owe|pay(?:ing)?) (?:a lot of|so much) tax\b|\btax (?:deductions?|relief)\b|\bhow (?:do I|to) (?:file|lower|reduce) (?:my )?tax",
        "A big tax bill usually means unused deductions — many are things you already pay for and just haven't claimed.",
        ["Check what you already pay that's deductible: social security, life or health insurance, mortgage interest, dependants, donations — keep the receipts.",
         "If buying more to deduct (retirement funds, insurance), make sure it suits your actual bracket and holding rules.",
         "Check the current list with your tax authority — items and caps change yearly (Thailand's Revenue Department: 1161)."],
        "Do you have insurance, mortgage interest or dependants this year?",
        "Taxable base = income − expenses − deductions; the variable still adjustable this year is deductions, starting with what you already pay."),
    "lease_cancel": (r"\b(?:break|end|get out of) (?:my|the|a) lease\b|\bmove out before (?:the )?(?:lease|contract) ends\b",
        "Leaving early has a price, but it's often negotiable — the lease sets the price, and notice plus finding a replacement tenant are your bargaining chips.",
        ["Read the clauses on early termination and the deposit: notice period and what you'd lose.",
         "Give written notice as early as possible and offer to find a replacement — landlords return more deposit when the room isn't empty.",
         "On move-out day, photograph every corner and ask for deductions in writing."],
        "What does your lease say about ending early?",
        "The cost of leaving is set by the contract and reduced by one variable — how long the place sits empty."),
    "noisy_neighbor": (r"\b(?:neighbou?rs?|upstairs|next door)\b[^\n]{0,30}?\b(?:loud|noise|noisy|music|parties)\b",
        "Noise every night is a nuisance with proper channels — escalate from light to heavy, because you'll keep living near each other, and a friendly word often works better than an immediate complaint.",
        ["Talk briefly in the daytime: 'The music after 10pm comes through to my place — could you turn it down?' Many people don't realise.",
         "If nothing changes, tell building management or the landlord, and log dates with recordings.",
         "If it continues, file a nuisance complaint with the local authority; police can be called for late-night disturbances."],
        "Have you spoken to them directly yet?",
        "Order by relationship cost: talk → management → authorities. The first is cheapest and most often works; keep evidence for the next."),
    "mule_police": (r"\b(?:police|summons)\b[^\n]{0,40}?\b(?:my (?:bank )?account)\b|\bmy (?:bank )?account (?:was|is being) used (?:to receive|for) (?:scam|fraud)",
        "You're now in a position where you'll need to explain — laws on 'money mule' accounts can hold the account holder responsible even without receiving money. The best protection is to attend with evidence and a lawyer.",
        ["Don't ignore the summons and don't delete any chats — gather how the account ended up with someone else (fake job, lost card, stolen details).",
         "Talk to a lawyer before giving a statement — you have the right to one (in Thailand, the Lawyers Council 1167 is free).",
         "Freeze every related account and app, and file your own report that you were deceived, if that's what happened."],
        "How did the account end up being used — did you hand it over, were you tricked, or did you not know at all?",
        "What decides the legal outcome is intent and evidence of how the account was used — keep evidence and get a lawyer, don't explain alone."),
    "kys_deduct": (r"\b(?:student loans?|student debt)\b[^\n]{0,40}?\b(?:can'?t (?:pay|afford)|payments?|deducted|garnish\w*|behind)\b|\bdrowning in student loan",
        "Student loan payments taken from salary are usually legal, not stolen wages — but amounts and terms can often be adjusted if you can't keep up.",
        ["Check your balance, monthly amount and account status with the lender.",
         "If what's left isn't enough to live on, ask about income-based repayment, restructuring or extending the term.",
         "If you've been sued, attend and ask for mediation — don't ignore it."],
        "How much is taken each month compared with what you have left to live on?",
        "The deduction is a legal mechanism, so it can't be reclaimed — the negotiable variables are monthly amount and term."),
    "study_behind": (r"\b(?:falling behind|can'?t keep up) (?:in|with) (?:class|school|my studies|lessons)\b",
        "Falling behind usually comes from a gap in earlier basics, not from not being smart — new topics build on old ones, so the gap grows until it's filled.",
        ["Go back chapter by chapter until you find one where you can still do the exercises; start rebuilding from the next.",
         "Ask your teacher or a classmate as soon as you get stuck, with a specific question.",
         "Do practice problems rather than rereading — try before checking the answer, and note repeated mistakes."],
        "From which topic did you start losing track?",
        "Knowledge in a subject is a stacked structure — find the missing layer and repair it, rather than rereading the current chapter."),
    "passport_seized": (r"\b(?:employer|boss|agent|agency)\b[^\n]{0,20}?\b(?:took|takes|kept|keeps|has|won'?t return)\b[^\n]{0,10}?\bmy (?:passport|id|documents)\b",
        "An employer keeping your passport isn't a normal part of work — it's a way to stop workers leaving, and a key sign of forced labour or trafficking. You have the right to hold your own documents.",
        ["Photograph every document you have (contract, payslips, workplace address, employer name) and store copies where the employer can't reach — send them to family or the cloud.",
         "Contact your country's embassy or consulate — they can help with documents and getting home. From Thailand, call 1300 (24h) to report trafficking.",
         "If you're locked in, threatened or hurt, contact local police and your embassy immediately — safety before unpaid wages."],
        "Can you leave your accommodation or workplace on your own right now?",
        "Freedom of movement is the risk variable: if restricted, it's an emergency; if not, the first goals are documents and an embassy contact."),
    "overseas_job_scam": (r"\b(?:recruiter|agent|agency)\b[^\n]{0,30}?\b(?:took|took my|charged)\b[^\n]{0,30}?\b(?:vanished|disappeared|blocked me|stopped replying)\b|\bjob abroad\b[^\n]{0,30}?\b(?:scam|afraid|safe)\b",
        "Overseas jobs that require a big upfront fee to an agent are where people get scammed most — the safe routes are licensed agencies or government programmes, and you can check before paying.",
        ["If you've already paid and can't reach them: report to police with transfer slips, chats and the receiving account, and to the labour/employment authority.",
         "If you haven't paid: check the agency's licence with the employment department (Thailand: 1694) and look for government-to-government programmes.",
         "Red flags: large upfront fees, tourist visas for work, no contract in your language, unusually high pay, pressure to decide fast."],
        "Have you paid yet, and do you have the slips or chats with the agent?",
        "The deciding variable is the agency's licence — checkable before paying. After paying, it's how fast you report with evidence."),
    "loan_shark": (r"\bloan shark\b|\b(?:informal|illegal) lender\b|\binterest (?:is )?(?:\d+%? )?(?:per|a|every) (?:day|week)\b",
        "Informal debt isn't heavy because you're bad with money — it's because the interest is so high the principal never falls. Many countries cap interest and ban threatening collection (Thailand caps it at 15% a year), so you have more options than the lender makes you feel.",
        ["Record every payment you've made — many people have already repaid more than the principal; it matters in mediation or a police report.",
         "Report illegal lending to police or the local authority (Thailand: Damrongtham Centre 1567). If threatened or attacked, call the police now.",
         "Get formal credit to pay off the most expensive debt, such as a state-bank small loan — formal interest is far lower."],
        "How much interest are you paying per day or month, and how much have you paid in total compared with what you borrowed?",
        "The interest outruns your ability to pay, so the principal never falls — the exit is changing lender or using your legal rights, not paying harder."),
    "debt_harass": (r"\b(?:debt )?collectors?\b[^\n]{0,30}?\b(?:call(?:ing)? my (?:friends|family|work|boss)|threaten\w*|harass\w*|shaming)\b|\bloan app\b[^\n]{0,30}?\b(?:calling|contacts|threaten|shaming)\b",
        "Owing money doesn't give collectors the right to shame or threaten you — debt collection laws usually ban telling others about your debt, threats and insults, and limit calling hours. Calling your whole contact list is their offence, not your shame.",
        ["Keep evidence: recordings, screenshots, call times. (In Thailand collectors may only call 8am–8pm on weekdays and 8am–6pm on holidays.)",
         "Report illegal collection to police or the debt-collection supervisory body; report unlicensed lending apps (Thailand: 1441).",
         "Warn people close to you that collectors may call — they shouldn't pay anything — then negotiate repayment in writing with the legitimate lender."],
        "Does this app or lender have a registered company name and licence, and who have they contacted?",
        "Separate two things: the debt (negotiate repayment) and illegal collection (report it). Being shamed doesn't add to the debt — it adds evidence for you."),
    "deceased_debt": (rf"\bmy {_KIN}\b[^\n]{{0,6}}?\b(?:died|passed away)\b[^\n]{{0,40}}?\bdebts?\b|\binherit(?:ed|ing)? (?:their |his |her )?debts?\b|\bdo I have to pay (?:his|her|their) debts?\b",
        "Heirs generally don't have to pay a deceased person's debts from their own money — in Thailand, liability is capped at what you inherit. If the estate is smaller than the debt, you don't pay the rest (unless you co-signed or borrowed jointly).",
        ["Don't sign anything accepting the debt or a repayment plan until you know the estate and all debts — signing can make it yours.",
         "Ask each creditor for documents and check which debts you co-signed or share (those are yours). Home and car loans often carry life insurance — check.",
         "Get legal advice on handling the estate (Thailand: Lawyers Council 1167, free)."],
        "Has a creditor asked you to sign anything yet, and what did they leave behind?",
        "Liability is capped by one variable — the estate's value — except what you sign yourself, so not signing more is the key protection."),
    "inheritance_dispute": (r"\b(?:fighting|arguing|dispute) over (?:the |our |my )?(?:\w+'?s? )?(?:inheritance|estate|will|land)\b|\bno will\b",
        "When there's no will, the law already sets heirs and shares — so the dispute isn't about who's loudest, but who administers the estate and who holds the documents.",
        ["Check the land office whether the property is still in the deceased's name or already transferred.",
         "If there's no administrator yet, heirs can apply to court, and object if someone unsuitable applies.",
         "Get legal advice before signing any consent or waiver — inheritance claims have time limits."],
        "Is there an estate administrator yet, and who has the title deeds?",
        "Power in an inheritance dispute sits with the administrator role and the title documents — know both before negotiating."),
    "funeral_cost": (r"\b(?:can'?t afford|no money for|pay for) (?:my \w+'?s |the |a )?funeral\b",
        "A simple funeral doesn't mean less love — and there's often help families don't know about while their hearts are heavy.",
        ["Check death benefits: social security, life insurance, funeral cooperatives or unions the person belonged to (Thailand: social security 1506).",
         "Families in hardship can ask the local social welfare office for funeral support (Thailand: 1300).",
         "Talk to the temple or funeral home about a simple service — many reduce costs for families who are struggling."],
        "Did they have social security through work, or life insurance?",
        "Funeral costs are more adjustable than they seem, and there may be unused entitlements — check them before borrowing."),
    "car_claim": (r"\b(?:hit my car|rear-?ended|car accident|crashed into)\b[^\n]{0,40}?\b(?:won'?t pay|refuses to pay|claim|insurance|drove off)\b",
        "If everyone is safe, this is now about evidence — whoever has the clearest evidence is who gets compensated.",
        ["Gather it now: photos of both cars, plates, the scene, dashcam footage, and ask nearby shops for CCTV quickly (often deleted within 7–30 days).",
         "Notify your insurer and file a police report. Compulsory insurance covers initial medical costs if anyone was hurt.",
         "If the other party won't pay and has no insurance, small-claims court is usually possible without a lawyer."],
        "Do you have photos, their plate number, or camera footage yet?",
        "The outcome is set by evidence gathered in the first days — CCTV is the variable that disappears fastest."),
    "insurance_denied": (r"\binsurance\b[^\n]{0,20}?\b(?:denied|rejected|refused|won'?t pay|won'?t cover)\b",
        "A denied claim isn't the final answer — the insurer must give reasons based on the policy, and many decisions are reversed with more documents or a complaint.",
        ["Ask for the denial in writing with the policy clause they rely on, and compare with your policy.",
         "Appeal with additional documents — treatment history, a doctor's note that it wasn't pre-existing.",
         "If that fails, complain to the insurance regulator (Thailand: OIC 1186), which mediates disputes for free."],
        "What reason did they give for not paying?",
        "Claim disputes turn on the policy wording and treatment records — get the reason in writing first so you know where to challenge."),
    "work_injury": (r"\b(?:got hurt|injured|broke my \w+|fell)\b[^\n]{0,20}?\b(?:at work|on the job|while working)\b|\bboss won'?t pay (?:for )?(?:my )?(?:treatment|medical)",
        "Work injuries are covered by workers' compensation, which employers already contribute to — you're claiming a right, not asking for kindness.",
        ["Get treated first and tell the hospital it's a work injury — keep the medical certificate and every receipt.",
         "Notify your employer in writing and file a workers' compensation claim (Thailand: Social Security 1506) — it covers treatment and lost wages.",
         "If the employer won't file, you can file yourself and report to the labour hotline (Thailand: 1546)."],
        "How long will you be off work, and does your employer know in writing?",
        "This is a funded right, not a negotiation — the key variable is documentation that it happened at work; file quickly."),
    "eviction": (r"\blandlord\b[^\n]{0,30}?\b(?:told me to move out|evict\w*|kicking me out|won'?t fix|won'?t return (?:my )?deposit|cut (?:off )?(?:the )?(?:water|power|electricity)|locked me out)\b",
        "A landlord can't simply throw you out or cut utilities if the lease is still running and you haven't breached it — your rights depend on the lease and proof of rent paid.",
        ["Read the lease on term, termination and deposit; without a written lease, rent receipts and chats are your evidence.",
         "Landlords must give notice before ending a tenancy — ask for it in writing with reasons; a few days' notice with no breach is negotiable.",
         "If utilities are cut, you're locked out or belongings are taken, call the police; for unfair deposit deductions use consumer protection (Thailand: 1166)."],
        "How long is left on the lease, and what reason did they give?",
        "Leverage depends on whether the lease is in force and who breached it — check both before deciding to move or fight."),
    "home_arrears": (r"\b(?:can'?t (?:pay|afford) (?:my|the) mortgage|behind on (?:my|the) mortgage|(?:house|home) (?:might|could|will) be (?:repossessed|foreclosed))\b",
        "A home loan has the most options before you're sued and the fewest after foreclosure — while you can still pay part, that's the best time to talk to the bank.",
        ["Contact the bank before falling far behind: ask for a principal holiday, a longer term or restructuring.",
         "Compare selling yourself (market price minus debt) with letting it go to auction, which usually fetches less and may leave debt.",
         "If you've been sued, attend and ask for mediation — not attending can mean losing by default."],
        "How many payments behind are you, and would selling now cover the loan?",
        "The deadline is the lawsuit and auction — before it you can restructure or sell; after it, most options disappear."),
    "mortgage_rejected": (r"\b(?:mortgage|home loan)\b[^\n]{0,20}?\b(?:rejected|denied|declined)\b",
        "A rejected application has findable reasons — usually debt-to-income too high, your credit report, or insufficient income documents. Know which before applying elsewhere.",
        ["Get your own credit report and look for late payments or forgotten accounts.",
         "Add up monthly debt (all loans plus the new mortgage) against income; if too high, pay off small debts first or add a co-borrower.",
         "Ask the bank why, then choose a lender suited to your work (freelancers and owners need different documents)."],
        "What do your other debts total each month compared with your income?",
        "Banks decide on three variables: debt-to-income, credit history, income stability — fix the worst before reapplying."),
    "buy_vs_rent": (r"\b(?:rent or buy|buy or rent|should I buy a (?:house|home|condo|flat|apartment))\b",
        "There's no single answer — the real questions are how long you'll stay and whether the payment will stretch your life too thin. A home with no buffer left is riskier than renting.",
        ["If work, family or city may change within five years, renting is often cheaper given buying and selling costs.",
         "If buying, keep total debt payments around a third of income or less, with six months' buffer after the down payment.",
         "Count hidden costs: transfer fees, maintenance, property tax, repairs and rate rises after any promotional period."],
        "How long do you expect to stay in this city?",
        "The deciding variables are how long you'll stay and the payment-to-income ratio — the longer and lower, the better buying looks."),
    "miscarriage": (r"\b(?:miscarriage|miscarried|lost (?:the|my|our) (?:baby|pregnancy))\b",
        "Losing a pregnancy is a real loss, even if people around you don't talk about it — and most miscarriages come from things nobody can control. It didn't happen because you did something wrong.",
        ["Let yourself grieve fully, without rushing to be 'better' — some people name the baby, write a letter, or hold a small ritual to say goodbye.",
         "If there's heavy bleeding, severe pain or fever, go to hospital. When ready, ask your doctor about causes and next time.",
         "If weeks pass and you still can't eat or sleep, or feel so guilty you don't want to live, reach out to a crisis line. Your partner may be grieving quietly too."],
        "Is there someone you can talk to about this?",
        "Medically, most miscarriages come from abnormalities no one controls — the guilt doesn't reflect what actually happened."),
    "infertility": (r"\btrying (?:for a baby|to (?:get pregnant|conceive))\b[^\n]{0,20}?\b(?:years?|months|no luck)\b|\b(?:infertility|ivf)\b",
        "Fertility trouble belongs to both partners, not just the woman — and the stress that builds month after month is as heavy as the treatment itself.",
        ["Get tested together — male factors are about as common as female ones.",
         "Over 35 and trying more than six months, or younger and over a year: see a fertility specialist.",
         "Agree on budget and limits before starting treatment, and keep some time where you don't talk about it."],
        "Have you both been tested?",
        "Treatment is a multi-step, costly decision — know both partners' causes and your budget first."),
    "menopause": (r"\b(?:menopause|perimenopause|hot flash(?:es)?|hot flush(?:es)?)\b",
        "Menopause symptoms come from real hormonal change — you're not imagining it or getting weaker, and many symptoms can be treated rather than endured in silence.",
        ["Log symptoms for 2–4 weeks and see a gynaecologist — there are hormonal and non-hormonal options.",
         "Dress in layers, cut caffeine and alcohol, exercise regularly, and get enough calcium as bones thin faster now.",
         "Tell people at home what's happening so mood swings become something understood, not fights."],
        "Which symptom affects daily life most right now?",
        "Symptoms come from a hormonal variable that can be measured and treated — enduring without testing doesn't make it pass faster."),
    "lgbt_self": (r"\bI'?m (?:gay|lesbian|bi(?:sexual)?|trans(?:gender)?|queer|non-?binary)\b[^\n]{0,30}?\b(?:afraid|scared|can'?t tell|haven'?t told|don'?t know how to tell|parents)\b",
        "There's nothing wrong with you, and you don't have to tell anyone before you're ready — coming out is yours to time. Think about safety first, especially if you depend on family for money or housing.",
        ["Find one safe person first — a friend, sibling or community group. One person who knows and understands helps a lot.",
         "If telling family, start with the person most likely to be open, at a calm moment, and expect that first reactions are rarely final.",
         "Thailand now has marriage equality and gender-discrimination protections. If you feel overwhelmed or alone, a support line can help (Thailand: 1323)."],
        "If you told your family, what worries you most — acceptance, or safety and money?",
        "Timing is set by safety and financial dependence — if you still rely on family, having a backup first lowers the risk."),
    "child_came_out": (r"\bmy (?:son|daughter|child|kid)\b[^\n]{0,20}?\b(?:told me|came out|just said)\b[^\n]{0,20}?\b(?:gay|lesbian|bi|trans|queer|likes (?:girls|boys))\b|\bmy (?:son|daughter|child|kid) is (?:gay|lesbian|bi|trans)\b",
        "Your child choosing to tell you means they trust you deeply — how parents react now affects their mental health more than almost anything. Young people whose families accept them have far lower depression risk.",
        ["Start by thanking them for telling you and saying you love them the same — you don't need every answer today.",
         "Your own confusion or worry is normal; work through it with someone else you trust, not on your child.",
         "Ask what they need from you now — maybe not telling relatives yet, or backup if they're teased at school."],
        "When they told you, how did you respond?",
        "What parents control is their own reaction, not their child's orientation — and that reaction directly shapes the child's emotional safety."),
    "elder_wander": (rf"\bmy {_KIN}\b[^\n]{{0,20}}?\b(?:dementia|alzheimer'?s|memory)\b[^\n]{{0,40}}?\b(?:wander\w*|gets lost|got lost|left the house|went missing)\b",
        "An older person with memory problems who wanders off is at risk of going missing or having an accident — prevent the next time now, and get the memory loss checked, since some causes are treatable.",
        ["If they're missing now: call the police immediately with a recent photo and what they're wearing — don't wait 24 hours.",
         "Prevent it: an ID bracelet with name and phone number, a door chime or hard-to-open lock, and a recent photo always on your phone.",
         "See a doctor for a memory assessment (thyroid, vitamins or medication can cause it) and ask about long-term care support."],
        "Are they safe at home now, or still missing?",
        "The highest risk is the next disappearance — cut it with simple variables: an ID tag, the door, and a current photo."),
    "online_harass": (r"\b(?:fake (?:account|profile)|impersonat\w+ me|using my photos|harass\w* me online|keeps? (?:messaging|dming) me)\b|\bwent viral\b[^\n]{0,20}?\b(?:hate|attack)",
        "Online harassment or impersonation isn't trivial and it isn't your fault — the evidence you save now is what lets platforms and police act.",
        ["Save evidence before blocking: screenshots with the account name, the URL and the date and time.",
         "Report the account to the platform (impersonation and harassment options) and ask friends to report the fake too. Set your own account private for now.",
         "If it continues, includes threats, or is used to scam others, report to police (Thailand: 1441)."],
        "Is it someone you know, or an account you can't identify?",
        "What makes it actionable is evidence tying the account to dates — save it before blocking, then use platform and police channels."),
    "teen_dating": (r"\bmy (?:teen(?:age)?|1[3-7]-year-old) (?:son|daughter|kid)\b[^\n]{0,20}?\b(?:has a (?:boyfriend|girlfriend)|is dating)\b|\bmy (?:son|daughter) (?:has a (?:boyfriend|girlfriend))\b",
        "Banning it outright usually makes teens hide things — and when problems come, they won't tell you. What protects them better is still being able to talk to you, with clear boundaries.",
        ["Ask to meet the partner — invite them over for a meal so you see a real person instead of guessing.",
         "Set clear rules with clear reasons — home time, letting you know where they are — agreed together works better than orders.",
         "Talk about safety for their age: consent, protection, signs of a controlling relationship — and that they can always call you without being scolded first."],
        "Did your child tell you about the relationship, or did you find out another way?",
        "What actually lowers risk is the communication channel your child still uses — if it closes, you won't hear what matters most."),
    "teen_trust": (r"\bmy (?:son|daughter|kid|child|teen)\b[^\n]{0,20}?\b(?:keeps? lying|lies all the time|steals? money|stealing money|took money)\b",
        "Lying or taking money is usually a symptom, not the problem — kids do it when something feels impossible to say directly: fear of punishment, being pressured, gaming or gambling, or wanting what friends have.",
        ["Talk when you're both calm and ask what the money was for, curious rather than interrogating.",
         "Watch for urgent signs: being extorted by peers, online gambling, in-game spending, or substance use.",
         "Set clear, proportionate consequences, and make it safe to tell the truth — honesty has to be safe before it can happen."],
        "Do you know what the money was used for?",
        "The same symptom has different causes — find where the money went, because extortion, gambling and wanting things need different fixes."),
    "child_dream": (r"\bmy (?:son|daughter|kid|child)\b[^\n]{0,30}?\b(?:youtuber|streamer|gamer|influencer|tiktoker|idol|singer)\b[^\n]{0,30}?\b(?:drop out|quit school|not study)\b|\bmy (?:son|daughter|kid|child)\b[^\n]{0,20}?\b(?:drop out|quit school)\b[^\n]{0,30}?\b(?:youtuber|streamer|gamer|influencer|tiktoker|idol|singer)\b",
        "Your child's dream and their education don't have to be either/or — ban it and they feel unheard; allow everything and there's no fallback. The middle path is a real trial with conditions.",
        ["Give it a serious go for a set period, like six months, with measurable goals (videos made, viewers), alongside schoolwork that must still pass.",
         "Look at real data together: what most people in that field earn, not just the famous few, and the skills needed (editing, marketing, languages).",
         "Agree a minimum together, like finishing a qualification, so the dream has a floor under it."],
        "Has your child started doing the thing yet, or is it still a wish?",
        "Lower the risk with a time-boxed trial and clear metrics — the result answers the question better than arguing."),
    "farm_loss": (r"\b(?:crop|rice|durian|rubber) prices?\b[^\n]{0,20}?\b(?:crash\w*|fell|dropped)\b|\b(?:flood|drought)\b[^\n]{0,20}?\b(?:destroyed|ruined|wiped out) (?:my|our|the) (?:crops?|farm|harvest|fields?)\b",
        "Price crashes and disasters are risks farmers can't control — what you can control is claiming support before deadlines and handling debt before it spirals.",
        ["If it was a natural disaster, register with the district agriculture office or village head quickly — relief has deadlines.",
         "Talk to your agricultural lender before defaulting about debt holidays or restructuring, and check crop insurance.",
         "Lower risk next season: don't plant one crop only, sell through cooperatives for better prices, and track cost per field."],
        "Was the loss from prices or from a disaster?",
        "Separate what you can't control (price, weather) from what you can (relief, debt, crop mix) — put your energy into the second."),
    "gig_income": (r"\b(?:delivery|rideshare|grab|uber|gig) (?:driver|rider|app|work)\b[^\n]{0,30}?\b(?:income (?:halved|dropped|fell)|no work|car broke|bike broke)\b|\bdrive for a delivery app\b",
        "Daily income rises and falls with things you can't control — platforms, weather, the economy — so stability doesn't come from working harder alone, but from multiple channels and a small buffer.",
        ["Work out net income per hour (after fuel, commission, repairs) by time slot and app — work the best-paying hours, not the longest.",
         "Open a second channel: several platforms, part-time steady work, or online selling — and get basic social insurance for sick days.",
         "If your vehicle needs repair, look for a low-interest small loan from a state bank before informal lenders — it's your earning tool."],
        "What's your net income per day after costs right now?",
        "This income must be measured as net per hour and volatility — reduce volatility with a second channel and a buffer."),
    "retire_savings": (r"\b(?:near(?:ly)? retirement|about to retire|I'?m (?:5\d|6\d))\b[^\n]{0,30}?\b(?:not enough|no savings|haven'?t saved|savings|enough saved)\b",
        "Planning late doesn't mean too late — it means using the variables still adjustable: working a bit longer, cutting unneeded costs and claiming every entitlement.",
        ["Count what you'll actually have: pension or social security, provident fund, old-age allowance and savings — against monthly costs.",
         "Each extra year of work, even at lower pay, helps twice: more income and slower drawdown. Clear debts before stopping work.",
         "Beware investments promising high returns to retirees — people your age are targeted most. Money needed within five years belongs somewhere safe."],
        "What monthly spending do you expect after retiring, and what income is certain?",
        "Retirement maths has three variables: assets, monthly cost, years to fund — each extra working year moves all three."),
    "old_alone": (r"\b(?:afraid|scared|worried) of (?:growing old|getting old|ageing|aging) alone\b|\bno one to (?:care for|look after) me when I'?m old\b",
        "Fearing old age without care is real for many people — but care in later life can be planned now, without relying only on children.",
        ["Build a network while healthy: neighbours, seniors' clubs, volunteer groups — people who know you notice when you're missing.",
         "Prepare money and rights: health insurance, a care fund, knowing state long-term care, and an advance directive for end-of-life treatment.",
         "Choose a home you can live in alone for long: near a hospital and market, no stairs, grab rails in the bathroom."],
        "Who do you stay in regular contact with now?",
        "The main risk of ageing alone is no one noticing when something happens — reduce it with a regular-contact network built while you're well."),
    "parents_move_in": (r"\b(?:my )?(?:parents|mom|mum|dad|mother-in-law|father-in-law)\b[^\n]{0,20}?\b(?:moving in|move in with (?:us|me)|come live with (?:us|me))\b",
        "Taking parents in is an act of care that needs a system — without agreements first, small things like space, noise and parenting become big fights.",
        ["Agree with your partner first, as a team: private space, shared costs and who handles what.",
         "Make the home safe for older people: ground-floor bedroom, bathroom rails, non-slip floors, night lights.",
         "If space is truly tight, try a middle path — a place nearby or rotating care with siblings."],
        "What does your partner think about this?",
        "What makes living together sustainable is agreeing space and roles before moving in — fixing it after is much harder."),
    "dept_transfer": (r"\b(?:transferred|moved) to (?:another|a different) (?:department|branch|role|city)\b[^\n]{0,30}?\b(?:without (?:asking|consent)|against my will|pay cut|less pay)\b",
        "A transfer that worsens your terms — lower pay, lower position, or too far to commute — usually can't be imposed one-sidedly, but moves within your role on equal terms often can.",
        ["Ask for the transfer order in writing with reasons and compare it with your contract and company rules.",
         "If pay, benefits or rank drop, reply in writing that you don't consent to worse terms — don't sign acceptance yet.",
         "Get free labour advice before resigning (Thailand: 1546) — if the move is meant to push you out, you may be owed severance."],
        "What gets worse with this transfer — pay, position or commute?",
        "The legal variable is whether your terms get worse — if so, consent is needed, so don't sign before knowing your rights."),
    "promotion_doubt": (r"\b(?:don'?t want to be (?:a )?(?:manager|boss|team lead)|promotion\b[^\n]{0,20}?\b(?:don'?t want|not sure|scared))\b",
        "Not wanting to manage doesn't mean not progressing — managing is a different job (people, decisions, pressure from both sides), not a reward for being good at the current one.",
        ["Name the fear precisely: lacking skills (trainable) or not wanting that kind of work (a different answer).",
         "Ask about an expert track with pay growth but no reports, or an acting period of three months before deciding.",
         "If you accept, ask for training and a mentor from day one — most new managers struggle because no one teaches them."],
        "If the role didn't come with more pay, would you still want that kind of work?",
        "Separate two variables that come bundled: more pay and a different job — if you only want the first, find a path to it without the second."),
    "older_jobseek": (r"\b(?:I'?m|at) (?:4\d|5\d|6\d)\b[^\n]{0,30}?\b(?:laid off|let go|fired|can'?t find (?:a )?job|no one will hire)\b",
        "Job hunting at an older age really is harder, as many employers look for cheaper hires — but experience is what younger people lack. Look for markets that value it rather than competing with graduates.",
        ["If you were laid off, check your severance by years of service, and register for unemployment benefits within the deadline.",
         "Target work that uses experience directly: consulting, training, contract work, small firms needing all-rounders.",
         "Refresh in-demand skills briefly (digital tools) and use your old network — most jobs at this age come through people you know."],
        "What's your deepest area of experience, and who knows you're looking?",
        "The channel that works changes with age — from job ads to personal networks. Put effort where experience is valued."),
    "procrastinate": (r"\bprocrastinat\w+\b|\bcan'?t (?:get )?started\b",
        "Procrastination is usually not laziness — it's escaping the discomfort a task brings (fear of doing it badly, not knowing where to start). So the fix is making the first step too small to fear.",
        ["Shrink the first step to five minutes, like 'open the file and write the headings' — starting is hardest; after that you often keep going.",
         "Work in fixed 25-minute blocks with your phone outside the room, then rest — don't wait to feel like it.",
         "Ask what this task makes you afraid of; if it's imperfection, aim for a first version that's allowed to be bad."],
        "For the task you're putting off, what's the smallest first step?",
        "The variable driving delay is the discomfort of starting, not task size — make starting as cheap as possible."),
    "screen_time": (r"\b(?:\d+ hours? (?:a|per) day on my phone|addicted to (?:my phone|social media|tiktok|scrolling)|doomscroll\w*|can'?t stop scrolling)\b",
        "Long phone use isn't a lack of willpower — apps are designed to be hard to stop. Changing your environment works better than relying on resolve.",
        ["Check screen-time reports for the app that takes the most time and set a limit on that one.",
         "Make it harder to grab: turn off non-human notifications, move apps off the home screen, charge the phone outside the bedroom.",
         "Ask what the phone fills in for — boredom, loneliness, stress — and find something else that fills part of that."],
        "When during the day is it hardest to put the phone down?",
        "This behaviour is driven by environment (notifications, app placement) — adjusting that works better than forcing yourself."),
    "purpose": (r"\b(?:don'?t know what I want (?:to do )?(?:with|in) (?:my )?life|don'?t know what I (?:like|love|want to do)|no purpose|no direction in life)\b",
        "What you love is rarely discovered by sitting and thinking — it's found while trying things. Not knowing now doesn't mean there's nothing; it means not enough has been tried yet.",
        ["Look back at when you lost track of time, or what people ask your help with — those are traces of strengths or interests.",
         "Try small things without commitment, one a month (a short course, volunteering, part-time work), and note what gives you energy.",
         "Change the question from 'what do I like?' to 'whose problem do I want to solve?' — it's easier to answer and leads to real work."],
        "When did you last lose track of time, and what were you doing?",
        "Interest is data you get from experiments, not from thinking — increase the number of small, cheap trials."),
    "belonging": (r"\b(?:don'?t (?:fit in|belong) anywhere|feel like an outsider|no one understands me)\b",
        "Not fitting in usually doesn't mean something's wrong with you — it means you haven't met people who share your interests or outlook yet. The right group is found through doing things together more than trying to join existing ones.",
        ["Join groups built around an interest — clubs, classes, volunteering, niche online communities. Doing things together builds closeness more easily than small talk.",
         "Invest in one or two people you feel at ease with rather than trying to fit with everyone.",
         "If this comes with sadness every day, or you stop wanting to go out, talk to a professional or a support line."],
        "What are you genuinely interested in but haven't found people to share it with?",
        "Belonging comes from frequency of contact around a shared interest — increase that variable rather than trying to change yourself."),
    "karma_fortune": (r"\b(?:is it (?:my )?karma|bad karma|bad luck (?:all the time|keeps happening)|fortune teller said)\b|\bkeep having bad luck\b",
        "Beliefs deserve respect — but however you see karma or fortune, what you can actually do today still lies in present action, which Buddhism itself emphasises over waiting for luck to change.",
        ["Break what's going wrong into real problems one by one (money, work, relationships, health), and find the one with a first step you can take — that's the part in your hands.",
         "If a ritual or offering brings you peace, continue — but don't pay large sums for rituals you're pressured into; it's a common scam.",
         "If feeling cursed comes with sadness every day, it may be emotional exhaustion worth getting support for."],
        "What feels heaviest in your life right now?",
        "Whatever you believe, the variable you can change is today's action — make the problems concrete and act on one with a clear first step."),
    "dental_fear": (r"\b(?:afraid|scared|terrified) of (?:the )?dentists?\b|\bdental (?:anxiety|phobia)\b",
        "Fear of the dentist is very common and usually comes from a painful past visit — but the longer you wait, the more damage builds, and treatment becomes more painful and expensive.",
        ["Tell the dentist upfront that you're afraid — they can adapt, with numbing gel before injections and a hand signal to pause.",
         "Start with the lightest visit: a check-up and cleaning, to get to know the dentist first.",
         "If there's swelling, fever or facial swelling, go now — dental infections can spread."],
        "What happened the time that made you afraid?",
        "The cost of delay grows with time — a small problem today becomes a root canal or extraction later, so going now is the least painful path."),
    "weight_gain": (r"\b(?:gained|put on) (?:\d+|a lot of|so much) (?:kg|kilos|pounds|lbs|weight)\b",
        "Weight that goes up fast usually has a cause in what changed in life (work, sleep, medication, stress) more than a lack of discipline — find that first, and losing it will last longer than dieting.",
        ["Look back at what changed when the weight started: less sleep, shift work, new medication, stress eating.",
         "Get checked: blood sugar, cholesterol, thyroid — rapid gain is sometimes a signal from the body.",
         "Change one thing you can do every day, like dropping one sugary drink or walking 30 minutes."],
        "When the weight started going up, what changed in your life?",
        "Weight is an output — the upstream variables are sleep, food, medication and stress. Fix whichever changed most recently."),
}

EN["solitude_need"] = (r"\b(?:need (?:some )?(?:space|time alone|time to myself)|no time (?:to myself|alone)|never (?:get to be )?alone|want to be alone (?:sometimes|for a while)|people all (?:day|the time))\b",
    "Wanting time alone isn't a problem, and it doesn't mean you love the people around you any less — nobody has to be with others all the time. "
    "Time with yourself is where you recharge, and once you have, you're better with others.",
    ["Find a short window that's truly yours every day, even 20–30 minutes — waking before others, a walk alone, sitting in the car before going in. Short and regular beats long and rare.",
     "Tell the people close to you plainly what you need and why: \"I need half an hour of quiet after work — I'm not upset with anyone, I just need to recharge.\"",
     "Notice your own rhythm: when time alone refreshes you, and when it starts to feel lonely. Everyone's balance is different, and it changes with life."],
    "If you had half an hour of your own every day, what would you use it for?",
    "Solitude is recharging, not retreating — what makes it happen is consistency and being clear with people around you, not the amount of time.")

